import com.fream.back.domain.m13.service.query.Xrd81QueryService;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.kafka.support.Acknowledgment;

import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;





class DeclinedCardOrderTest {

    private static final String REAL_PACKAGE = "com.fream.back.domain.m06.service.command";

    private final Map<Class<?>, Object> mocks = new HashMap<>();


    private <T> T assemble(Class<T> type) throws Exception {
        Constructor<?> c = Arrays.stream(type.getDeclaredConstructors())
                .max(Comparator.comparingInt(Constructor::getParameterCount)).orElseThrow();
        Class<?>[] types = c.getParameterTypes();
        Object[] args = new Object[types.length];
        for (int i = 0; i < types.length; i++) {
            Class<?> t = types[i];
            boolean concrete = !t.isInterface() && !Modifier.isAbstract(t.getModifiers());
            args[i] = (concrete && t.getName().startsWith(REAL_PACKAGE))
                    ? assemble(t)
                    : mocks.computeIfAbsent(t, Mockito::mock);
        }
        return type.cast(c.newInstance(args));
    }

    @SuppressWarnings("unchecked")
    private <T> T mockOf(Class<T> type) {
        return (T) mocks.computeIfAbsent(type, Mockito::mock);
    }

    @Test
    void declinedCard_keepsOrderWaitingForPayment_andCreatesNoShipment() throws Exception {
        Xdg64EventConsumer consumer = assemble(Xdg64EventConsumer.class);

        Xrd81 buyer = Xrd81.builder().id(1L).email("buyer@test.com").build();
        Xdg64 order = Xdg64.builder().id(100L).user(buyer).totalAmount(30000)
                .status(Xdg64Status.PENDING_PAYMENT).build();

        when(mockOf(Xdg64Repository.class).findById(100L)).thenReturn(Optional.of(order));
        when(mockOf(Xrd81QueryService.class).findByEmail("buyer@test.com")).thenReturn(buyer);
        when(mockOf(Xbf54Repository.class).save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(mockOf(Xbf54InfoQueryService.class).getPaymentInfoEntity(eq("buyer@test.com"), eq(7L)))
                .thenReturn(Xbf54Info.builder().cardNumber("1234567812345678").build());

        when(mockOf(Xxv33ApiClient.class).processCardPayment(any(), anyDouble()))
                .thenReturn(Map.of("status", "failed", "fail_reason", "한도 초과", "imp_uid", "imp_declined"));

        Xrt49RequestDto request = Xrt49RequestDto.builder()
                .paymentRequest(Xqg94RequestDto.builder()
                        .orderId(100L).userEmail("buyer@test.com").paidAmount(30000).paymentInfoId(7L).build())
                .receiverName("홍길동").receiverPhone("01011112222").postalCode("06236").address("서울시 강남구")
                .warehouseStorage(false)
                .build();

        consumer.handleOrderProcessingEvent(
                Xmr97Event.create(100L, "buyer@test.com", request), mock(Acknowledgment.class));


        verify(mockOf(Xxv33ApiClient.class)).processCardPayment(any(), eq(30000.0));

        assertThat(order.getStatus()).isEqualTo(Xdg64Status.PENDING_PAYMENT);
        verify(mockOf(Xhx14CommandService.class), never())
                .createOrderShipment(any(), anyString(), anyString(), anyString(), anyString());
    }
}
package com.fream.back.domain.m06.service.kafka;

import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m16.repository.Xdg64Repository;
import com.fream.back.domain.m06.dto.kafka.Xbf54Event;
import com.fream.back.domain.m06.entity.Xbf54;
import com.fream.back.domain.m06.exception.Xbf54Exception;
import com.fream.back.domain.m06.repository.Xbf54Repository;
import com.fream.back.domain.m06.service.command.Xbf54CommandService;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.service.query.Xrd81QueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.kafka.support.KafkaHeaders;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.Optional;





@Service
@RequiredArgsConstructor
@Slf4j
public class Xbf54EventConsumer {

    private final Xbf54CommandService paymentCommandService;
    private final Xbf54EventProducer paymentEventProducer;
    private final Xdg64Repository orderRepository;
    private final Xbf54Repository paymentRepository;
    private final Xrd81QueryService userQueryService;





    @KafkaListener(
            topics = "payment-processing-topic",
            groupId = "payment-processing-group",
            containerFactory = "paymentEventKafkaListenerContainerFactory"
    )
    @Transactional
    public void handlePaymentEvent(
            @Payload Xbf54Event event,
            @Header(KafkaHeaders.RECEIVED_PARTITION) int partition,
            @Header(KafkaHeaders.OFFSET) long offset,
            Acknowledgment acknowledgment) {

        Instant start = Instant.now();

        try {
            log.info("결제 처리 이벤트 수신: 주문ID={}, 이벤트ID={}, 파티션={}, 오프셋={}",
                    event.getOrderId(), event.getEventId(), partition, offset);


            if (isPaymentAlreadyProcessed(event.getOrderId())) {
                log.warn("이미 처리된 결제 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Xdg64 order = orderRepository.findById(event.getOrderId())
                    .orElseThrow(() -> new IllegalArgumentException(
                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));


            Xrd81 user = userQueryService.findByEmail(event.getUserEmail());


            if (!order.getUser().getId().equals(user.getId())) {
                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
                        event.getOrderId(), order.getUser().getId(), user.getId());
                throw new Xbf54Exception(null, "주문과 사용자 정보가 일치하지 않습니다.");
            }


            Xbf54 payment = paymentCommandService.processPayment(order, user, event.getPaymentRequest());

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 결제상태={}",
                    event.getOrderId(), payment.getId(), payment.getStatus());


            acknowledgment.acknowledge();


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.info("결제 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());

        } catch (Xbf54Exception e) {
            log.error("결제 처리 실패 (Xbf54Exception): 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            handlePaymentFailure(event, e, acknowledgment);

        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            handlePaymentFailure(event, e, acknowledgment);
        }
    }




    @KafkaListener(
            topics = "payment-retry-topic",
            groupId = "payment-retry-group",
            containerFactory = "paymentEventKafkaListenerContainerFactory"
    )
    @Transactional
    public void handlePaymentRetryEvent(
            @Payload Xbf54Event event,
            Acknowledgment acknowledgment) {

        try {
            log.info("결제 재시도 처리: 주문ID={}, 재시도횟수={}",
                    event.getOrderId(), event.getRetryCount());


            if (event.isMaxRetryExceeded()) {
                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
                        event.getOrderId(), event.getRetryCount());
                acknowledgment.acknowledge();
                return;
            }


            if (isPaymentAlreadyProcessed(event.getOrderId())) {
                log.info("재시도 중 결제 완료 확인: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));


            handlePaymentEvent(event, 0, 0, acknowledgment);

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.error("결제 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
            acknowledgment.acknowledge();
        } catch (Exception e) {
            log.error("결제 재시도 처리 중 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private boolean isPaymentAlreadyProcessed(Long orderId) {
        try {
            Optional<Xbf54> existingPayment = paymentRepository.findByOrder_Id(orderId);

            if (existingPayment.isPresent()) {
                Xbf54 payment = existingPayment.get();
                log.info("기존 결제 발견: 주문ID={}, 결제ID={}, 결제상태={}",
                        orderId, payment.getId(), payment.getStatus());


                return payment.isSuccess();
            }

            return false;
        } catch (Exception e) {
            log.error("결제 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
            return false;
        }
    }




    private void handlePaymentFailure(Xbf54Event event, Exception error, Acknowledgment acknowledgment) {
        try {

            if (isRetryableError(error)) {
                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
                paymentEventProducer.sendPaymentRetryEvent(event);
            } else {
                log.error("재시도 불가능한 오류로 결제 실패 처리: 주문ID={}, 오류={}",
                        event.getOrderId(), error.getMessage());

            }

            acknowledgment.acknowledge();

        } catch (Exception e) {
            log.error("결제 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private boolean isRetryableError(Exception error) {

        return !(error instanceof IllegalArgumentException) &&
                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
    }
}package com.fream.back.domain.m06.entity;

import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.global.entity.Xwb79Entity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;

@Entity @jakarta.persistence.Table(name = "payment")
@Getter
@NoArgsConstructor
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
@DiscriminatorColumn(name = "payment_type")
public abstract class Xbf54 extends Xwb79Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xdg64 order;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xgg74 sale;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false)
    private Xrd81 user;

    @Column(nullable = false)
    private double paidAmount;
    @Column(nullable = false)
    private boolean isSuccess = false;

    private LocalDateTime paymentDate;

    @Enumerated(EnumType.STRING)
    private Xbf54Status status = Xbf54Status.PENDING;


    public void assignOrder(Xdg64 order) {
        this.order = order;
        this.sale = null;
    }

    public void assignSale(Xgg74 sale) {
        this.sale = sale;
        this.order = null;
    }
    public void assignUser(Xrd81 user) {
        this.user = user;
    }

    public void setPaidAmount(double paidAmount) {
        this.paidAmount = paidAmount;
        this.isSuccess = paidAmount > 0;
    }
    public void updateSuccessStatus(boolean success) {
        this.isSuccess = success;
        if (success) {
            this.paymentDate = LocalDateTime.now();
        }
    }
    public void updateStatus(Xbf54Status newStatus) {
        if (this.status.canTransitionTo(newStatus)) {
            this.status = newStatus;
        } else {
            throw new IllegalStateException("결제 상태 전환이 허용되지 않습니다: " + this.status + " -> " + newStatus);
        }
    }

    public abstract String getImpUid();
}
package com.fream.back.domain.m06.entity;

import jakarta.persistence.DiscriminatorValue;
import jakarta.persistence.Entity;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Getter
@NoArgsConstructor
@DiscriminatorValue("ACCOUNT")
public class Xkg34 extends Xbf54 {

    private String impUid;
    private String bankName;
    private String accountNumber;
    private String accountHolder;
    private boolean receiptRequested;

    @Builder
    public Xkg34(String bankName, String accountNumber, String accountHolder,
                          boolean receiptRequested, double paidAmount) {
        this.bankName = bankName;
        this.accountNumber = accountNumber;
        this.accountHolder = accountHolder;
        this.receiptRequested = receiptRequested;
        this.setPaidAmount(paidAmount);
    }
    @Override
    public String getImpUid() {
        return this.impUid;
    }

}package com.fream.back.domain.m06.entity;

public enum Xbf54Status {
    PENDING,
    PAID,
    REFUND_REQUESTED,
    REFUNDED,
    FAILED;

    public boolean canTransitionTo(Xbf54Status newStatus) {
        switch (this) {
            case PENDING:
                return newStatus == PAID;
            case PAID:
                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
            case REFUND_REQUESTED:
                return newStatus == REFUNDED;
            default:
                return false;
        }
    }
}

