public enum Xbf54Status {
    PENDING,
    PAID,
    REFUND_REQUESTED,
    REFUNDED,
    FAILED;

    public boolean canTransitionTo(Xbf54Status newStatus) {
        switch (this) {
            case PENDING:
                return newStatus == PAID;
            case PAID:
                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
            case REFUND_REQUESTED:
                return newStatus == REFUNDED;
            default:
                return false;
        }
    }
