@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
@Slf4j
public class Xbf54QueryService {

    private final Xbf54Repository paymentRepository;







    public Xbf54Dto getPaymentDetails(Long paymentId) {
        Instant start = Instant.now();
        try {
            if (paymentId == null) {
                throw new Xvt76Exception("결제 ID가 제공되지 않았습니다.");
            }

            log.info("결제 정보 조회 시작: 결제ID={}", paymentId);

            Xbf54 payment = paymentRepository.findById(paymentId)
                    .orElseThrow(() -> new Xvt76Exception("결제 ID: " + paymentId + "를 찾을 수 없습니다."));

            Xbf54Dto paymentDto = convertToDto(payment);

            log.info("결제 정보 조회 완료: 결제ID={}, 결제유형={}",
                    paymentId, paymentDto.getPaymentType());
            return paymentDto;
        } catch (Xbf54Exception e) {
            log.error("결제 정보 조회 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    paymentId, e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 정보 조회 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    paymentId, e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                    "결제 정보 조회 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 정보 조회 처리 시간: {}ms", duration.toMillis());
        }
    }







    public List<Xbf54Dto> getUserPayments(String email, boolean success) {
        Instant start = Instant.now();
        try {
            if (email == null || email.isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_ACCESS_DENIED,
                        "사용자 이메일 정보가 없습니다.");
            }

            log.info("사용자 결제 내역 조회 시작: 사용자={}, 성공여부={}", email, success);

            List<Xbf54> payments = paymentRepository.findByOrder_User_EmailAndIsSuccess(email, success);

            List<Xbf54Dto> result = payments.stream()
                    .map(this::convertToDto)
                    .toList();

            log.info("사용자 결제 내역 조회 완료: 사용자={}, 조회된 결제 수={}", email, result.size());
            return result;
        } catch (Xbf54Exception e) {
            log.error("사용자 결제 내역 조회 실패: 사용자={}, 에러코드={}, 메시지={}",
