            log.debug("사용자 결제 내역 조회 처리 시간: {}ms", duration.toMillis());
        }
    }







    public List<Xbf54Dto> getSellerPayments(String email, boolean success) {
        Instant start = Instant.now();
        try {
            if (email == null || email.isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_ACCESS_DENIED,
                        "판매자 이메일 정보가 없습니다.");
            }

            log.info("판매자 수금 내역 조회 시작: 판매자={}, 성공여부={}", email, success);

            List<Xbf54> payments = paymentRepository.findBySale_Seller_EmailAndIsSuccess(email, success);

            List<Xbf54Dto> result = payments.stream()
                    .map(this::convertToDto)
                    .toList();

            log.info("판매자 수금 내역 조회 완료: 판매자={}, 조회된 결제 수={}", email, result.size());
