            throw e;
        } catch (Exception e) {
            log.error("판매자 수금 내역 조회 중 예상치 못한 오류 발생: 판매자={}, 오류={}",
                    email, e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                    "판매자 수금 내역 조회 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
