import com.fream.back.domain.m06.entity.Xbf54Status;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;





@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xkx75Event {




    private Long paymentId;




    private Long orderId;




    private String userEmail;




    private Integer paidAmount;




    private Xbf54Status paymentStatus;




    private Boolean isSuccess;




    private LocalDateTime paymentCompletedAt;




    private String paymentMethod;




    private String impUid;




    private LocalDateTime eventCreatedAt;




    private String eventId;

    public static Xkx75Event create(Long paymentId, Long orderId, String userEmail,
                                               Integer paidAmount, Xbf54Status status, Boolean isSuccess,
                                               String paymentMethod, String impUid) {
        return Xkx75Event.builder()
                .paymentId(paymentId)
                .orderId(orderId)
                .userEmail(userEmail)
                .paidAmount(paidAmount)
                .paymentStatus(status)
                .isSuccess(isSuccess)
                .paymentCompletedAt(LocalDateTime.now())
                .paymentMethod(paymentMethod)
                .impUid(impUid)
                .eventCreatedAt(LocalDateTime.now())
                .eventId(generateEventId(paymentId, orderId))
                .build();
    }

    private static String generateEventId(Long paymentId, Long orderId) {
        return "payment_completed_" + orderId + "_" + paymentId + "_" + System.currentTimeMillis();
    }




    public boolean isPaymentSuccess() {
        return Boolean.TRUE.equals(this.isSuccess) &&
                Xbf54Status.PAID.equals(this.paymentStatus);
    }




    public boolean isPaymentFailed() {
        return Boolean.FALSE.equals(this.isSuccess) ||
                Xbf54Status.FAILED.equals(this.paymentStatus);
    }
}

