            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                    "사용자 결제 내역 조회 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("사용자 결제 내역 조회 처리 시간: {}ms", duration.toMillis());
        }
    }







    public List<Xbf54Dto> getSellerPayments(String email, boolean success) {
        Instant start = Instant.now();
        try {
            if (email == null || email.isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_ACCESS_DENIED,
                        "판매자 이메일 정보가 없습니다.");
            }

            log.info("판매자 수금 내역 조회 시작: 판매자={}, 성공여부={}", email, success);

            List<Xbf54> payments = paymentRepository.findBySale_Seller_EmailAndIsSuccess(email, success);

            List<Xbf54Dto> result = payments.stream()
                    .map(this::convertToDto)
                    .toList();

            log.info("판매자 수금 내역 조회 완료: 판매자={}, 조회된 결제 수={}", email, result.size());
            return result;
        } catch (Xbf54Exception e) {
            log.error("판매자 수금 내역 조회 실패: 판매자={}, 에러코드={}, 메시지={}",
                    email, e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("판매자 수금 내역 조회 중 예상치 못한 오류 발생: 판매자={}, 오류={}",
                    email, e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                    "판매자 수금 내역 조회 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("판매자 수금 내역 조회 처리 시간: {}ms", duration.toMillis());
        }
    }






    public Xqg94Dto findByImpUid(String impUid) {
        try {
            if (impUid == null || impUid.isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                        "결제 고유 ID(impUid)가 제공되지 않았습니다.");
            }

            log.info("ImpUid로 결제 정보 조회 시작: impUid={}", impUid);

            Xqg94 payment = paymentRepository.findByImpUid(impUid)
                    .orElse(null);

            if (payment == null) {
                log.info("ImpUid에 해당하는 결제 정보 없음: impUid={}", impUid);
                return null;
            }

            Xqg94Dto result = Xqg94Dto.fromEntity(payment);
            log.info("ImpUid로 결제 정보 조회 완료: impUid={}, 결제ID={}", impUid, result.getId());
            return result;
        } catch (Xbf54Exception e) {
            log.error("ImpUid로 결제 정보 조회 실패: impUid={}, 에러코드={}, 메시지={}",
                    impUid, e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("ImpUid로 결제 정보 조회 중 예상치 못한 오류 발생: impUid={}, 오류={}",
                    impUid, e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_RETRIEVAL_FAILED,
                    "결제 고유 ID로 결제 정보 조회 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private Xbf54Dto convertToDto(Xbf54 payment) {
        if (payment instanceof Xjt86 generalPayment) {
            return Xjt86Dto.fromEntity(generalPayment);
        } else if (payment instanceof Xqg94 cardPayment) {
            return Xqg94Dto.fromEntity(cardPayment);
        } else if (payment instanceof Xkg34 accountPayment) {
            return Xkg34Dto.fromEntity(accountPayment);
        } else {
            log.error("알 수 없는 결제 유형: 결제ID={}, 결제유형={}",
                    payment.getId(), payment.getClass().getSimpleName());
            throw new Xfg84TypeException(
                    "알 수 없는 결제 유형입니다: " + payment.getClass().getSimpleName());
        }
    }
