package com.fream.back.domain.m06.entity;

import jakarta.persistence.DiscriminatorValue;
import jakarta.persistence.Entity;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Getter
@NoArgsConstructor
@DiscriminatorValue("CARD")
public class Xqg94 extends Xbf54 {

    private String cardNumber;
    private String cardPassword;
    private String cardExpiration;
    private String birthDate;
    private String cardType;
    private String impUid;
    private String receiptUrl;
    private String pgProvider;
    private String pgTid;

    @Builder
    public Xqg94(String cardNumber, String cardPassword, String cardExpiration, String birthDate,
                       String cardType, double paidAmount, String impUid, String receiptUrl,
                       String pgProvider, String pgTid) {
        this.cardNumber = cardNumber;
        this.cardPassword = cardPassword;
        this.cardExpiration = cardExpiration;
        this.birthDate = birthDate;
        this.cardType = cardType;
        this.impUid = impUid;
        this.receiptUrl = receiptUrl;
        this.pgProvider = pgProvider;
        this.pgTid = pgTid;
        this.setPaidAmount(paidAmount);
    }
    @Override
    public String getImpUid() {
        return this.impUid;
    }
}
